package model

import (
	"context"
	"encoding/json"
	"strings"
)

// Correlation metadata stays in the existing Other column. XResponseID always
// denotes the response generated by this request, never its parent.
func AppendResponseCorrelationOther(ctx context.Context, other string) string {
	parent := PreviousResponseIDFromContext(ctx)
	origin, known := ResponseOriginFromContext(ctx)
	if parent == "" && !known {
		return other
	}
	metadata := map[string]any{"previous_response_id": parent}
	if known {
		metadata["origin_region"] = origin.Region
		metadata["origin_channel_type"] = origin.ChannelType
		metadata["origin_channel_id"] = origin.ChannelID
		metadata["origin_key_index"] = origin.KeyIndex
	}
	var object map[string]json.RawMessage
	if json.Unmarshal([]byte(other), &object) == nil && object != nil {
		raw, _ := json.Marshal(metadata)
		object["responseCorrelation"] = raw
		encoded, _ := json.Marshal(object)
		return string(encoded)
	}
	encoded, _ := json.Marshal(metadata)
	segment := "responseCorrelation:" + string(encoded)
	if strings.TrimSpace(other) == "" {
		return segment
	}
	return strings.TrimRight(other, ";") + ";" + segment
}
